#!/usr/bin/env node
// scripts/check-shim-artifacts.mjs
//
// Presence + shape guard for the two hand-authored package-root artifacts
// shipped for downstream project tsconfigs (#2656): `tsconfig.base.json` and
// `zfb-config-shim.d.ts`. Unlike the other check-*.mjs guards in this
// directory, these files are NOT build outputs — they are hand-authored,
// checked straight into git — so this guard exists to catch a deleted/emptied
// file or a broken tsconfig shape rather than a missed build step. (The third
// shipped artifact, `virtual-modules.d.ts`, IS a build output — generated by
// copy-virtual-modules.mjs — and has its own guard, check-virtual-modules.mjs.)
// Run as a prepack hook so a broken shim fails loudly instead of publishing a
// package whose `tsconfig.base.json` `files: [...]` references dangle for
// consumers.
//
// Exit 0 → both files exist, are non-empty, `tsconfig.base.json` is valid
//          JSON, ships the shims via a TOP-LEVEL `files` (not nested in
//          compilerOptions, not via `include`), and that `files` array names
//          exactly the two shipped shim files.
// Exit 1 → any check fails (with a clear diagnostic message).

import { readFileSync, statSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PKG_ROOT = resolve(__dirname, "..");

const REQUIRED_FILES = ["tsconfig.base.json", "zfb-config-shim.d.ts"];

let ok = true;

for (const rel of REQUIRED_FILES) {
  const abs = resolve(PKG_ROOT, rel);
  let size = 0;
  try {
    size = statSync(abs).size;
  } catch {
    process.stderr.write(`\n[check-shim-artifacts] ERROR: ${rel} is missing.\n\n`);
    ok = false;
    continue;
  }
  if (size === 0) {
    process.stderr.write(`\n[check-shim-artifacts] ERROR: ${rel} exists but is empty.\n\n`);
    ok = false;
    continue;
  }
  process.stdout.write(`[check-shim-artifacts] ${rel} OK (${size} bytes)\n`);
}

if (!ok) process.exit(1);

// ── tsconfig.base.json shape ────────────────────────────────────────────────

let base;
try {
  base = JSON.parse(readFileSync(resolve(PKG_ROOT, "tsconfig.base.json"), "utf-8"));
} catch (err) {
  process.stderr.write(
    `\n[check-shim-artifacts] ERROR: tsconfig.base.json is not valid JSON: ${err instanceof Error ? err.message : String(err)}\n\n`,
  );
  process.exit(1);
}

// `files` (like `include`/`exclude`) is a TOP-LEVEL tsconfig field, not a
// compilerOptions field — TS rejects it under compilerOptions with TS5023
// "Unknown compiler option 'files'". Guard against that regression too.
if (base.compilerOptions != null && "files" in base.compilerOptions) {
  process.stderr.write(
    `\n[check-shim-artifacts] ERROR: tsconfig.base.json has "files" nested inside ` +
      `"compilerOptions" — "files" is a TOP-LEVEL tsconfig field (TS5023 "Unknown\n` +
      `  compiler option 'files'" otherwise). Move it alongside "compilerOptions".\n\n`,
  );
  process.exit(1);
}

// Q5 trap (spike #2652): `files`/`include`/`exclude` are OVERRIDE-only across
// `extends` — the extending project's own value replaces the base's, and a
// base value applies only when the project declares none of its own. So a
// base-level `include` is wrong in BOTH directions: an extends-only project
// tsconfig would inherit ONLY the shim-include and silently skip its own
// files (the spike's planted error passed), while a project that declares
// its own `include` silently discards the base's (shims drop out). Shipping
// via base `files` is safe because the minimal project tsconfig declares
// `include` but never a top-level `files`, so the base's `files` is inherited
// alongside the project's `include`.
if ("include" in base || "exclude" in base) {
  process.stderr.write(
    `\n[check-shim-artifacts] ERROR: tsconfig.base.json must not carry a top-level ` +
      `"include"/"exclude" — it ships the ambient shims via top-level "files"\n` +
      `  only (Q5 trap: include/exclude/files are override-only across extends;\n` +
      `  a base "include" either becomes the whole program for an extends-only\n` +
      `  project or is silently discarded by a project's own "include").\n` +
      `  See the file's header comment and packages/zudo-doc/CLAUDE.md.\n\n`,
  );
  process.exit(1);
}

const expectedFiles = ["./zfb-config-shim.d.ts", "./virtual-modules.d.ts"];
const actualFiles = Array.isArray(base.files) ? base.files : [];
const filesMatch =
  actualFiles.length === expectedFiles.length &&
  expectedFiles.every((f) => actualFiles.includes(f));

if (!filesMatch) {
  process.stderr.write(
    `\n[check-shim-artifacts] ERROR: tsconfig.base.json top-level "files" must be ` +
      `exactly ${JSON.stringify(expectedFiles)}, got ${JSON.stringify(actualFiles)}.\n\n`,
  );
  process.exit(1);
}

process.stdout.write(`[check-shim-artifacts] tsconfig.base.json shape OK\n`);
